public class MatVecTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("2x2 times {5,6}", "[17.0, 39.0]", java.util.Arrays.toString(
                MatVec.multiply(new double[][]{{1, 2}, {3, 4}}, new double[]{5, 6})));
        check("2x3 times {7,8,9}", "[7.0, 8.0]", java.util.Arrays.toString(
                MatVec.multiply(new double[][]{{1, 0, 0}, {0, 1, 0}}, new double[]{7, 8, 9})));
        check("1x1 times {3}", "[6.0]", java.util.Arrays.toString(
                MatVec.multiply(new double[][]{{2}}, new double[]{3})));
        check("3x2 times {4,3}", "[7.0, 1.0, 8.0]", java.util.Arrays.toString(
                MatVec.multiply(new double[][]{{1, 1}, {1, -1}, {2, 0}}, new double[]{4, 3})));
        check("identity 3x3 times {1,2,3}", "[1.0, 2.0, 3.0]", java.util.Arrays.toString(
                MatVec.multiply(new double[][]{{1, 0, 0}, {0, 1, 0}, {0, 0, 1}}, new double[]{1, 2, 3})));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

