public class MatVec {

    public static double[] multiply(double[][] m, double[] v) {
        double[] result = new double[m.length];
        for (int r = 0; r < m.length; r++) {
            double sum = 0.0;
            for (int c = 0; c < v.length; c++) {
                sum += m[r][c] * v[c];
            }
            result[r] = sum;
        }
        return result;
    }
}
